#!/usr/bin/env bash
# Generated by `node scripts/npm-trust.ts` — do not edit. Run it ONCE, by hand, after the first publish (npm needs the packages
# to exist): every package trusts the release workflow for STAGED publishing only — a staged version goes live when a
# maintainer approves it with 2FA on npmjs.com (E152). Needs npm >= 11.15 and an `npm login` with 2FA. The first call asks
# for the one-time password; tick "skip two-factor authentication for the next 5 minutes" there, and the rest runs through.
set -euo pipefail

packages=(
  @bespokecore/auth
  bespokecore
  @bespokecore/cache
  @bespokecore/cli
  @bespokecore/core
  create-bespoke-app
  @bespokecore/database
  @bespokecore/devtools
  @bespokecore/encryption
  @bespokecore/http
  @bespokecore/i18n
  @bespokecore/live
  @bespokecore/log
  @bespokecore/mail
  @bespokecore/notifications
  @bespokecore/otel
  @bespokecore/queue
  @bespokecore/react
  @bespokecore/redis
  @bespokecore/router
  @bespokecore/scheduler
  @bespokecore/server
  @bespokecore/session
  @bespokecore/storage
  @bespokecore/testing
  @bespokecore/vite
)

for package in "${packages[@]}"; do
  npm trust github "$package" --repository bespokecore/bespokecore --file release.yml --allow-stage-publish --yes
  sleep 2 # npm asks for a pause between calls (rate limit)
done

echo "Trusted release.yml of bespokecore/bespokecore (staged publishing) for ${#packages[@]} packages. Check one: npm trust list @bespokecore/auth"
